CREATE TABLE vai_tro (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ten_vai_tro VARCHAR NOT NULL UNIQUE, mo_ta VARCHAR, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE nguoi_dung (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_vai_tro BIGINT NOT NULL REFERENCES vai_tro(id) ON DELETE RESTRICT, ten_dang_nhap VARCHAR NOT NULL UNIQUE, mat_khau_ma_hoa VARCHAR NOT NULL, ho_va_ten VARCHAR NOT NULL, so_dien_thoai VARCHAR, dang_hoat_dong BOOLEAN NOT NULL DEFAULT TRUE, ngay_tao TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE ca_lam_viec (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_thu_ngan BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE RESTRICT, thoi_gian_bat_dau TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, thoi_gian_ket_thuc TIMESTAMPTZ, tien_dau_ca DECIMAL(12,2) NOT NULL DEFAULT 0, tien_ket_ca DECIMAL(12,2), trang_thai VARCHAR NOT NULL DEFAULT 'DANG_MO', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE loai_san_pham (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ten_danh_muc VARCHAR NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE san_pham (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_danh_muc BIGINT NOT NULL REFERENCES loai_san_pham(id) ON DELETE RESTRICT, ten_san_pham VARCHAR NOT NULL, mo_ta TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE bien_the_san_pham (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_san_pham BIGINT NOT NULL REFERENCES san_pham(id) ON DELETE RESTRICT, kich_co VARCHAR NOT NULL, gia_ban DECIMAL(12,2) NOT NULL, so_luong_ton DECIMAL(10,2) NOT NULL DEFAULT 0, con_hang BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ, UNIQUE(ma_san_pham, kich_co));
CREATE TABLE topping (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ten_topping VARCHAR NOT NULL, gia_ban DECIMAL(12,2) NOT NULL, so_luong_ton DECIMAL(10,2) NOT NULL DEFAULT 0, con_hang BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE ban (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, so_ban VARCHAR NOT NULL UNIQUE, ma_qr_token VARCHAR NOT NULL UNIQUE, trang_thai VARCHAR NOT NULL DEFAULT 'TRONG', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE khach_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, so_dien_thoai VARCHAR NOT NULL UNIQUE, email VARCHAR, ho_va_ten VARCHAR, mat_khau_ma_hoa VARCHAR, diem_tich_luy INT NOT NULL DEFAULT 0, hang_thanh_vien VARCHAR NOT NULL DEFAULT 'DONG', token_lam_moi VARCHAR, da_xac_thuc BOOLEAN NOT NULL DEFAULT FALSE, ngay_tao TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE gio_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_khach_hang BIGINT REFERENCES khach_hang(id) ON DELETE SET NULL, token_phien VARCHAR NOT NULL, thoi_gian_cap_nhat TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE chi_tiet_gio_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_gio_hang BIGINT NOT NULL REFERENCES gio_hang(id) ON DELETE CASCADE, ma_bien_the BIGINT NOT NULL REFERENCES bien_the_san_pham(id) ON DELETE RESTRICT, so_luong INT NOT NULL DEFAULT 1 CHECK (so_luong > 0), muc_duong VARCHAR, muc_da VARCHAR, ghi_chu_mon VARCHAR, thanh_tien DECIMAL(12,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE topping_gio_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_chi_tiet_gio BIGINT NOT NULL REFERENCES chi_tiet_gio_hang(id) ON DELETE CASCADE, ma_topping BIGINT NOT NULL REFERENCES topping(id) ON DELETE RESTRICT, so_luong INT NOT NULL DEFAULT 1 CHECK (so_luong > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE chuong_trinh_khuyen_mai (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ten_chuong_trinh VARCHAR NOT NULL, mo_ta TEXT, ngay_bat_dau TIMESTAMPTZ NOT NULL, ngay_ket_thuc TIMESTAMPTZ NOT NULL, dang_hoat_dong BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE khuyen_mai_san_pham (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_chuong_trinh BIGINT NOT NULL REFERENCES chuong_trinh_khuyen_mai(id) ON DELETE CASCADE, ma_san_pham BIGINT REFERENCES san_pham(id) ON DELETE RESTRICT, ma_danh_muc BIGINT REFERENCES loai_san_pham(id) ON DELETE RESTRICT, loai_giam_gia VARCHAR NOT NULL, gia_tri_giam DECIMAL(12,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ, CHECK (ma_san_pham IS NOT NULL OR ma_danh_muc IS NOT NULL));
CREATE TABLE khuyen_mai_hoa_don (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_chuong_trinh BIGINT NOT NULL REFERENCES chuong_trinh_khuyen_mai(id) ON DELETE CASCADE, don_hang_toi_thieu DECIMAL(12,2) NOT NULL DEFAULT 0, loai_giam_gia VARCHAR NOT NULL, gia_tri_giam DECIMAL(12,2) NOT NULL, muc_giam_toi_da DECIMAL(12,2), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE khuyen_mai_voucher (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_chuong_trinh BIGINT NOT NULL REFERENCES chuong_trinh_khuyen_mai(id) ON DELETE CASCADE, ma_code VARCHAR NOT NULL UNIQUE, loai_giam_gia VARCHAR NOT NULL, gia_tri_giam DECIMAL(12,2) NOT NULL, muc_giam_toi_da DECIMAL(12,2), don_hang_toi_thieu DECIMAL(12,2) NOT NULL DEFAULT 0, gioi_han_su_dung INT, so_luot_da_dung INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE don_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_hien_thi_don VARCHAR NOT NULL UNIQUE, kenh_dat_hang VARCHAR NOT NULL, ma_ca BIGINT REFERENCES ca_lam_viec(id) ON DELETE SET NULL, ma_thu_ngan BIGINT REFERENCES nguoi_dung(id) ON DELETE SET NULL, ma_khach_hang BIGINT REFERENCES khach_hang(id) ON DELETE SET NULL, ma_ban BIGINT REFERENCES ban(id) ON DELETE SET NULL, ma_voucher BIGINT REFERENCES khuyen_mai_voucher(id) ON DELETE SET NULL, loai_phuc_vu VARCHAR NOT NULL, tong_tien_hang DECIMAL(12,2) NOT NULL, so_tien_giam DECIMAL(12,2) NOT NULL DEFAULT 0, tong_tien_thanh_toan DECIMAL(12,2) NOT NULL, trang_thai VARCHAR NOT NULL DEFAULT 'CHO_XAC_NHAN', ngay_tao TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE chi_tiet_don_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_don_hang BIGINT NOT NULL REFERENCES don_hang(id) ON DELETE CASCADE, ma_bien_the BIGINT NOT NULL REFERENCES bien_the_san_pham(id) ON DELETE RESTRICT, so_luong INT NOT NULL DEFAULT 1 CHECK (so_luong > 0), don_gia DECIMAL(12,2) NOT NULL, muc_duong VARCHAR, muc_da VARCHAR, ghi_chu_mon VARCHAR, thanh_tien DECIMAL(12,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE topping_don_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_chi_tiet_don BIGINT NOT NULL REFERENCES chi_tiet_don_hang(id) ON DELETE CASCADE, ma_topping BIGINT NOT NULL REFERENCES topping(id) ON DELETE RESTRICT, so_luong INT NOT NULL DEFAULT 1 CHECK (so_luong > 0), don_gia DECIMAL(12,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE giao_dich_thanh_toan (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_don_hang BIGINT NOT NULL REFERENCES don_hang(id) ON DELETE RESTRICT, phuong_thuc_thanh_toan VARCHAR NOT NULL, so_tien DECIMAL(12,2) NOT NULL, noi_dung_vietqr TEXT, trang_thai VARCHAR NOT NULL DEFAULT 'CHO_XU_LY', thoi_gian_thanh_toan TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE nha_cung_cap (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ten_nha_cung_cap VARCHAR NOT NULL, so_dien_thoai VARCHAR NOT NULL, email VARCHAR, dia_chi VARCHAR, ma_so_thue VARCHAR, nguoi_dai_dien VARCHAR, dang_hop_tac BOOLEAN NOT NULL DEFAULT TRUE, ngay_tao TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE phieu_nhap_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_phieu_nhap VARCHAR NOT NULL UNIQUE, ma_nha_cung_cap BIGINT NOT NULL REFERENCES nha_cung_cap(id) ON DELETE RESTRICT, ma_nguoi_nhap BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE RESTRICT, tong_tien DECIMAL(12,2) NOT NULL DEFAULT 0, ghi_chu TEXT, trang_thai VARCHAR NOT NULL DEFAULT 'DA_NHAP_KHO', ngay_nhap TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ);
CREATE TABLE chi_tiet_phieu_nhap (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ma_phieu_nhap BIGINT NOT NULL REFERENCES phieu_nhap_hang(id) ON DELETE CASCADE, ma_bien_the BIGINT REFERENCES bien_the_san_pham(id) ON DELETE RESTRICT, ma_topping BIGINT REFERENCES topping(id) ON DELETE RESTRICT, ten_mat_hang VARCHAR NOT NULL, don_vi_tinh VARCHAR NOT NULL, so_luong DECIMAL(10,2) NOT NULL DEFAULT 1, don_gia_nhap DECIMAL(12,2) NOT NULL, thanh_tien DECIMAL(12,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMPTZ, CHECK (ma_bien_the IS NOT NULL OR ma_topping IS NOT NULL));
